def merge_accounts(accounts):
    n = len(accounts)
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1

    email_to_index = {}
    for i, account in enumerate(accounts):
        for email in account[1:]:
            if email in email_to_index:
                union(i, email_to_index[email])
            else:
                email_to_index[email] = i

    groups = {}
    for email, idx in email_to_index.items():
        root = find(idx)
        groups.setdefault(root, set()).add(email)

    result = []
    for root, emails in groups.items():
        name = accounts[root][0]
        sorted_emails = sorted(emails)
        result.append([name] + sorted_emails)

    result.sort(key=lambda acc: (acc[0], acc[1]))
    return result
